#!/usr/bin/env python3
"""Prepara el árbol GPL Gearmulator para alojar el motor nativo sin interfaz GUI.

Solo modifica la copia de código fuente descargada en el runner, nunca una ROM.
"""
import argparse
from pathlib import Path

CMAKE_INTEGRATION = """
# BEGIN OSTIRUS_NATIVE_HOST (generated by OsTIrus Web)
if(DEFINED OSTIRUS_NATIVE_HOST_SOURCE)
    add_executable(ostirus_native_host "${OSTIRUS_NATIVE_HOST_SOURCE}")
    target_compile_features(ostirus_native_host PRIVATE cxx_std_17)
    target_link_libraries(ostirus_native_host PRIVATE virusLib)
    if(APPLE)
        target_link_libraries(ostirus_native_host PRIVATE "-framework AudioToolbox" "-framework CoreAudio")
    endif()
endif()
# END OSTIRUS_NATIVE_HOST
"""

HEADLESS_THIRDPARTY = """# Headless native build: GUI is intentionally disabled.
# Original Gearmulator GPL sources remain unmodified elsewhere.
cmake_minimum_required(VERSION 3.15)
add_library(rmlui_core INTERFACE)
add_library(rmlui_debugger INTERFACE)
add_library(freetype INTERFACE)
add_library(Freetype::Freetype ALIAS freetype)
"""


def apply(root: Path):
    root = root.resolve()
    thirdparty = root / "source/3rdparty/CMakeLists.txt"
    top = root / "CMakeLists.txt"
    old = thirdparty.read_text(encoding="utf-8")
    cmake = top.read_text(encoding="utf-8")
    if "Stub for WASM build" not in old and old != HEADLESS_THIRDPARTY:
        raise ValueError("No se reconoce CMake 3rdparty original")
    if "project(gearmulator VERSION 2.2.2)" not in cmake:
        raise ValueError("No se reconoce la raíz Gearmulator")
    if "BEGIN OSTIRUS_NATIVE_HOST" not in cmake:
        cmake += "\n" + CMAKE_INTEGRATION
    thirdparty.write_text(HEADLESS_THIRDPARTY, encoding="utf-8")
    top.write_text(cmake, encoding="utf-8")
    print("Preparación nativa de OsTIrus lista; sin firmware ni GUI")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("source", type=Path)
    args = parser.parse_args()
    apply(args.source)


if __name__ == "__main__":
    main()
